    let web: String
    let swift: String?
    let marker: String?
    let excluded: String?
    init(web: String, swift: String, marker: String) { self.web = web; self.swift = swift; self.marker = marker; self.excluded = nil }
    init(web: String, excluded: String) { self.web = web; self.swift = nil; self.marker = nil; self.excluded = excluded }
    var component: String { String(web.split(separator: ".").first ?? "") }
}

